function renderCommercialActions() { const pending = workspace.pricingContracts.filter((item) => item.status === "pending_approval"); ui.contract_actions.replaceChildren(...pending.map((item) => { const row = document.createElement("article"); row.className = "lifecycle-item"; const button = document.createElement("button"); button.type = "button"; button.className = "btn btn-secondary btn-sm"; button.dataset.approveContract = item.contractId; button.textContent = "Approve contract"; row.append(text("strong", item.contractId), text("small", "Independent commercial approval required."), button); return row; })); }
function renderBudgetActions() { const budgets = workspace.usageBudgets ?? []; const pending = budgets.filter((item) => item.status === "pending_approval"); ui.budget_actions.replaceChildren(...pending.map((item) => { const row = document.createElement("article"); row.className = "lifecycle-item"; const button = text("button", "Approve spending limit"); button.type = "button"; button.className = "btn btn-secondary btn-sm"; button.dataset.approveBudget = item.budgetId; row.append(text("strong", item.budgetId), text("small", `Maximum ₹${paiseToRupees(item.limits.maxChargePaise)} · independent finance approval required`), button); return row; })); const active = budgets.filter((item) => item.status === "active"); ui.budget_monitor.className = active.length ? "preview-grid" : "preview-grid empty"; ui.budget_monitor.replaceChildren(...(active.length ? active.map((item) => previewItem(item.budgetId, `Approved ceiling ₹${paiseToRupees(item.limits.maxChargePaise)} · valid until ${new Date(item.validUntil).toLocaleDateString("en-IN")}`)) : [text("span", "No approved spending limits.")])); }
function renderActivationSelectors() { const pending = workspace.installations.filter((item) => item.status === "pending_approval"); const options = [option("", pending.length ? "Select a pending installation" : "No pending installation") , ...pending.map((item) => option(item.installationId, `${item.installationId} · ${Object.keys(item.approvedByRole ?? {}).length}/4 approvals`))]; ui.approval_installation.replaceChildren(...options); ui.activation_installation.replaceChildren(...options.map((item) => item.cloneNode(true))); const all = [option("", "Select an assistant"), ...workspace.installations.map((item) => option(item.installationId, item.installationId))]; ui.test_installation.replaceChildren(...all.map((item) => item.cloneNode(true))); ui.compare_from.replaceChildren(...all.map((item) => item.cloneNode(true))); ui.compare_to.replaceChildren(...all.map((item) => item.cloneNode(true))); ui.version_installation.replaceChildren(...all.map((item) => item.cloneNode(true))); ui.rollback_installation.replaceChildren(...all.map((item) => item.cloneNode(true))); ui.provider_installation.replaceChildren(...all.map((item) => item.cloneNode(true))); ui.version_test_run.replaceChildren(option("", "Select a passing rehearsal"), ...(workspace.testRuns ?? []).filter((item) => item.status === "passed").map((item) => option(item.runId, `${item.runId} · ${item.scorePercent}%`))); ui.rollback_version.replaceChildren(option("", "Select a published version"), ...(workspace.agentVersions ?? []).map((item) => option(item.versionId, `${item.versionId} · version ${item.versionNumber}`))); ui.memory_store_id.replaceChildren(option("", "Not required"), ...(workspace.memoryStores ?? []).filter((item) => item.status === "active").map((item) => option(item.memoryStoreId, item.name))); if (ui.workflow_select) ui.workflow_select.replaceChildren(option("", "Not required"), ...(workspace.workflowDrafts ?? []).map((item) => option(item.workflowId, `${item.name} (${item.steps.length} steps)`))); }

function renderWorkflowCanvas() { ui.workflow_steps.replaceChildren(...workflowSteps.map((step, index) => { const card = document.createElement("article"); card.className = "workflow-step"; const number = text("span", String(index + 1)); number.className = "step-number"; const select = document.createElement("select"); select.dataset.stepType = index; for (const [value, label] of [["receive", "Receive a case"], ["check", "Check information"], ["prepare", "Prepare a draft"], ["request_information", "Request information"], ["route", "Route to a team"], ["human_review", "Human review"], ["notify", "Prepare a notification"], ["close", "Close the task"]]) select.append(option(value, label)); select.value = step.type; const input = document.createElement("input"); input.value = step.label; input.dataset.stepLabel = index; input.setAttribute("aria-label", `Step ${index + 1} description`); const remove = document.createElement("button"); remove.type = "button"; remove.className = "btn btn-secondary btn-sm"; remove.dataset.removeStep = index; remove.textContent = "Remove"; card.append(number, select, input, remove); return card; })); ui.workflow_steps.querySelectorAll("select,input").forEach((field) => field.addEventListener("change", updateWorkflowStep)); }
function updateWorkflowStep(event) { const index = Number(event.target.dataset.stepType ?? event.target.dataset.stepLabel); if (event.target.dataset.stepType !== undefined) workflowSteps[index].type = event.target.value; else workflowSteps[index].label = event.target.value; }
function workflowStepAction(event) { const button = event.target.closest("[data-remove-step]"); if (!button || workflowSteps.length <= 2) return; workflowSteps.splice(Number(button.dataset.removeStep), 1); renderWorkflowCanvas(); }
async function submitWorkflow(event) { event.preventDefault(); const form = new FormData(ui.workflow_form); try { await request("/ai/agents/workflows", { method: "POST", body: JSON.stringify({ workflowId: form.get("workflow-id") ?? document.getElementById("workflow-id").value, name: document.getElementById("workflow-id").value, templateId: selectedTemplate.templateId, productTypes: split(document.getElementById("workflow-products").value), steps: workflowSteps }) }); setStatus("Work plan saved as a governed draft."); await load(); } catch (error) { setStatus(error.message, true); } }
