async function submitMemoryStore(event) { event.preventDefault(); const get = (id) => document.getElementById(id).value; try { const name = get("memory-store-name"); await request("/ai/agents/memory-stores", { method: "POST", body: JSON.stringify({ memoryStoreId: slug(name), name, purpose: get("memory-purpose"), allowedFields: split(get("memory-fields")), region: "ap-south-1", retentionDays: Number(get("memory-retention")), consentRef: get("memory-consent-ref"), accessPolicyRef: get("memory-access-ref"), correctionProcessRef: get("memory-correction-ref"), deletionProcessRef: get("memory-deletion-ref"), legalHoldPolicyRef: get("memory-hold-ref"), encryptionRef: get("memory-encryption-ref") }) }); setStatus("Memory store proposed. Persistent memory remains unavailable until privacy approval."); ui.memory_form.reset(); await load(); } catch (error) { setStatus(error.message, true); } }
async function approveMemoryStore(event) { const button = event.target.closest("[data-approve-memory]"); if (!button) return; const approvalRef = window.prompt("Independent privacy approval reference:"); if (!approvalRef?.trim()) return; try { await request(`/ai/agents/memory-stores/${encodeURIComponent(button.dataset.approveMemory)}/approve`, { method: "POST", body: JSON.stringify({ approvalRef: approvalRef.trim() }) }); setStatus("Governed memory store approved for its declared purpose and fields."); await load(); } catch (error) { setStatus(error.message, true); } }
