function renderMemoryStores() { const records = workspace.memoryStores ?? []; if (!records.length) return renderRecords(ui.memory_list, [], () => ""); ui.memory_list.className = "lifecycle-list"; ui.memory_list.replaceChildren(...records.map((item) => { const row = document.createElement("article"); row.className = "lifecycle-item"; row.append(text("strong", item.name), text("small", `${item.status} · ${item.retentionDays} days · ${item.allowedFields.join(", ")} · India region`)); if (item.status === "pending_approval") { const button = text("button", "Approve as privacy checker"); button.type = "button"; button.className = "btn btn-secondary btn-sm"; button.dataset.approveMemory = item.memoryStoreId; row.append(button); } return row; })); }
function renderTestSuites() { const suites = workspace.testSuites ?? []; if (!suites.length) { ui.test_list.className = "lifecycle-list empty"; ui.test_list.textContent = "No test sets yet."; return; } ui.test_list.className = "lifecycle-list"; ui.test_list.replaceChildren(...suites.map((suite) => { const row = document.createElement("article"); row.className = "lifecycle-item"; const button = text("button", "Rehearse controls"); button.type = "button"; button.className = "btn btn-secondary btn-sm"; button.dataset.runSuite = suite.suiteId; row.append(text("strong", suite.name), text("small", `${suite.caseCount} cases · includes adverse testing`), button); return row; })); }
function renderTestResults() { const runs = workspace.testRuns ?? []; if (!runs.length) { ui.test_results.className = "preview-grid empty"; ui.test_results.textContent = "No rehearsal results yet."; return; } ui.test_results.className = "preview-grid"; ui.test_results.replaceChildren(...runs.slice(-4).map((run) => previewItem(`${run.status === "passed" ? "Passed" : "Needs attention"} · ${run.scorePercent}%`, `${run.passedCount}/${run.caseCount} cases · adverse ${run.adversePassed ? "passed" : "failed"} · synthetic rehearsal`))); }
function renderRollbacks() { const records = workspace.rollbackRequests ?? []; if (!records.length) { ui.rollback_list.className = "lifecycle-list empty"; ui.rollback_list.textContent = "No rollback requests."; return; } ui.rollback_list.className = "lifecycle-list"; ui.rollback_list.replaceChildren(...records.map((record) => { const row = document.createElement("article"); row.className = "lifecycle-item"; row.append(text("strong", record.rollbackId), text("small", `${record.targetVersionId} · ${record.status} · ${record.reason}`)); if (record.status === "pending_approval") { const button = text("button", "Approve as independent checker"); button.type = "button"; button.className = "btn btn-secondary btn-sm"; button.dataset.approveRollback = record.rollbackId; row.append(button); } return row; })); }
function renderReleaseReadiness() { const installation = workspace.installations.find((item) => item.installationId === ui.version_installation.value); const run = (workspace.testRuns ?? []).find((item) => item.runId === ui.version_test_run.value); const cards = [readinessItem(Boolean(run?.status === "passed"), run?.status === "passed" ? "All rehearsal cases passed" : "Passing rehearsal needed", run ? `${run.scorePercent}% · adverse ${run.adversePassed ? "passed" : "failed"}` : "Run the normal and difficult cases."), readinessItem(Object.keys(installation?.approvedByRole ?? {}).length === 4, `${Object.keys(installation?.approvedByRole ?? {}).length}/4 human approvals`, "Owner, validator, reviewer and model-risk manager must be independent."), readinessItem(false, "Live-provider certification separate", "Publishing here versions configuration; it does not admit a live model provider." )]; ui.release_readiness.className = "readiness-grid"; ui.release_readiness.replaceChildren(...cards); }
function renderRecords(container, records = [], detail) { if (!records.length) { container.className = "lifecycle-list empty"; return; } container.className = "lifecycle-list"; container.replaceChildren(...records.map((item) => { const row = document.createElement("article"); row.className = "lifecycle-item"; row.append(text("strong", item.name), text("small", detail(item))); return row; })); }
async function commercialAction(event) { const button = event.target.closest("[data-approve-contract]"); if (!button) return; const approvalRef = window.prompt("Commercial approval reference:"); if (!approvalRef?.trim()) return; try { await request(`/ai/pricing-contracts/${encodeURIComponent(button.dataset.approveContract)}/approve`, { method: "POST", body: JSON.stringify({ commercialApprovalRef: approvalRef.trim() }) }); setStatus("Contract approved for entitled installations."); await load(); } catch (error) { setStatus(error.message, true); } }
async function submitBudget(event) { event.preventDefault(); const until = new Date(ui.budget_valid_until.value); if (!ui.budget_contract.value || Number.isNaN(until.getTime())) return setStatus("Budget requires an active contract and end date.", true); try { const limits = { maxExecutions: "999999", maxInputTokens: "999999999", maxOutputTokens: "999999999", maxChargePaise: rupeesToPaise(ui.budget_paise.value) }; await request("/ai/usage-budgets", { method: "POST", body: JSON.stringify({ budgetId: ui.budget_id.value, contractId: ui.budget_contract.value, limits, effectiveFrom: new Date().toISOString(), validUntil: until.toISOString() }) }); setStatus("Hard usage budget proposed for independent approval."); ui.budget_form.reset(); await load(); } catch (error) { setStatus(error.message, true); } }
async function approveBudget(event) { const button = event.target.closest("[data-approve-budget]"); if (!button) return; const approvalRef = window.prompt("Independent finance approval reference:"); if (!approvalRef?.trim()) return; try { await request(`/ai/usage-budgets/${encodeURIComponent(button.dataset.approveBudget)}/approve`, { method: "POST", body: JSON.stringify({ commercialApprovalRef: approvalRef.trim() }) }); setStatus("Spending limit approved with an exact hard ceiling."); await load(); } catch (error) { setStatus(error.message, true); } }
async function submitApproval(event) { event.preventDefault(); if (!ui.approval_installation.value || !ui.approval_ref.value.trim()) return setStatus("Select the installation and enter an independent approval reference.", true); try { await request(`/ai/agents/installations/${encodeURIComponent(ui.approval_installation.value)}/approvals/${encodeURIComponent(ui.approval_role.value)}`, { method: "POST", body: JSON.stringify({ approvalRef: ui.approval_ref.value.trim() }) }); setStatus("Approval recorded if your authenticated role and independence requirements are satisfied."); ui.approval_form.reset(); await load(); } catch (error) { setStatus(error.message, true); } }
async function submitActivation(event) { event.preventDefault(); const form = new FormData(ui.activation_form); const governanceEvidence = Object.fromEntries([...form.entries()].filter(([key]) => key !== "installationId")); if (!ui.activation_installation.value) return setStatus("Select a pending installation for activation.", true); try { await request(`/ai/agents/installations/${encodeURIComponent(ui.activation_installation.value)}/activate`, { method: "POST", body: JSON.stringify({ governanceEvidence }) }); setStatus("Activation completed only after the isolated control engine allowed the current evidence and staffing state."); ui.activation_form.reset(); await load(); } catch (error) { setStatus(error.message, true); } }
function renderInstallations() { const installations = [...workspace.installations].sort((a, b) => b.createdAt.localeCompare(a.createdAt)); if (!installations.length) { ui.installation_list.className = "lifecycle-list empty"; ui.installation_list.textContent = "No tenant installations yet."; return; } ui.installation_list.className = "lifecycle-list"; ui.installation_list.replaceChildren(...installations.map((installation) => { const item = document.createElement("article"); item.className = "lifecycle-item"; const approvals = Object.keys(installation.approvedByRole ?? {}).length; item.append(text("strong", installation.installationId), text("span", `${installation.templateId} · ${installation.status} · ${approvals}/4 approvals`), text("small", `Model ${installation.modelId} ${installation.modelVersion} · ${installation.allowedActions.join(", ")}`)); const actions = document.createElement("div"); actions.className = "inline-actions"; const exportButton = text("button", "Export setup"); exportButton.type = "button"; exportButton.className = "btn btn-secondary btn-sm"; exportButton.dataset.exportId = installation.installationId; actions.append(exportButton); if (installation.status === "active") { const button = text("button", "Suspend"); button.type = "button"; button.className = "btn btn-danger btn-sm"; button.dataset.suspendId = installation.installationId; actions.append(button); } if (installation.status !== "retired") { const retire = text("button", "Retire"); retire.type = "button"; retire.className = "btn btn-secondary btn-sm"; retire.dataset.retireId = installation.installationId; actions.append(retire); } item.append(actions); return item; })); }
async function lifecycleAction(event) { const exportButton = event.target.closest("[data-export-id]"); if (exportButton) { try { const record = await request(`/ai/agents/installations/${encodeURIComponent(exportButton.dataset.exportId)}/export`); downloadJson(`${exportButton.dataset.exportId}.json`, record); setStatus("Configuration exported without approvals or borrower data."); } catch (error) { setStatus(error.message, true); } return; } const retireButton = event.target.closest("[data-retire-id]"); if (retireButton) { const reason = window.prompt("Why is this assistant being retired?"); if (!reason?.trim()) return; try { await request(`/ai/agents/installations/${encodeURIComponent(retireButton.dataset.retireId)}/retire`, { method: "POST", body: JSON.stringify({ reason: reason.trim(), exportRef: `agent-studio/export/${retireButton.dataset.retireId}` }) }); setStatus("Assistant retired. Its evidence and history remain available."); await load(); } catch (error) { setStatus(error.message, true); } return; } const button = event.target.closest("[data-suspend-id]"); if (!button) return; const reason = window.prompt("Reason for immediate suspension (required):"); if (!reason?.trim()) return; const incidentRef = window.prompt("Incident reference (required):"); if (!incidentRef?.trim()) return; try { await request(`/ai/agents/installations/${encodeURIComponent(button.dataset.suspendId)}/suspend`, { method: "POST", body: JSON.stringify({ reason: reason.trim(), incidentRef: incidentRef.trim() }) }); setStatus("Installation suspended. New execution authorization is blocked."); await load(); } catch (error) { setStatus(error.message, true); } }
async function renderReport() { try { const report = await request("/ai/agents/governance-report"); const metrics = report.summary ?? report; const entries = Object.entries(metrics).filter(([, value]) => typeof value === "number" || typeof value === "string").slice(0, 8); if (!entries.length) { ui.report_content.className = "preview-grid empty"; ui.report_content.textContent = "No governed activity yet."; return; } ui.report_content.className = "preview-grid"; ui.report_content.replaceChildren(...entries.map(([key, value]) => previewItem(key.replaceAll(/([A-Z])/g, " $1"), String(value)))); } catch (error) { ui.report_content.className = "preview-grid empty"; ui.report_content.textContent = `Report unavailable: ${error.message}`; } }
function renderOperationsQueue() { const role = ui.role_view.value; const records = (workspace.operationsQueue ?? []).filter((item) => role === "all" || role === "business" || item.ownerRole === role); if (!records.length) { ui.operations_queue.className = "lifecycle-list empty"; ui.operations_queue.textContent = "Nothing needs attention for this view."; return; } ui.operations_queue.className = "lifecycle-list"; ui.operations_queue.replaceChildren(...records.map((item) => { const row = document.createElement("article"); row.className = `lifecycle-item queue-${item.severity}`; row.append(text("strong", item.title), text("small", `Owner: ${item.ownerRole.replaceAll("_", " ")} · due ${new Date(item.dueAt).toLocaleDateString("en-IN")}`)); if (item.type === "proposal_review") { const actions = document.createElement("div"); actions.className = "inline-actions"; const accept = text("button", "Confirm proposal"); accept.type = "button"; accept.className = "btn btn-primary btn-sm"; accept.dataset.reviewExecution = item.resourceId; accept.dataset.reviewDisposition = "accepted"; const send = text("button", "Return to team"); send.type = "button"; send.className = "btn btn-secondary btn-sm"; send.dataset.reviewExecution = item.resourceId; send.dataset.reviewDisposition = "returned_for_changes"; actions.append(accept, send); row.append(actions); } return row; })); }
async function reviewProposal(event) { const button = event.target.closest("[data-review-execution]"); if (!button) return; const reviewRef = window.prompt("Your review record reference (required):"); if (!reviewRef?.trim()) return; try { await request(`/ai/agents/executions/${encodeURIComponent(button.dataset.reviewExecution)}/human-review`, { method: "POST", body: JSON.stringify({ disposition: button.dataset.reviewDisposition, reviewRef: reviewRef.trim() }) }); setStatus("Your review is recorded against the proposal's audit trail. The assistant cannot act on it without you."); await load(); } catch (error) { setStatus(error.message, true); } }
async function submitProviderEvidence(event) { event.preventDefault(); const get = (id) => document.getElementById(id).value; try { await request("/ai/agents/provider-evidence", { method: "POST", body: JSON.stringify({ evidenceId: get("provider-evidence-id"), installationId: ui.provider_installation.value, providerId: get("provider-id"), region: "ap-south-1", contractRef: get("provider-contract-ref"), securityRef: get("provider-security-ref"), residencyRef: get("provider-residency-ref"), monitoringRef: get("provider-monitoring-ref"), incidentExerciseRef: get("provider-incident-ref"), institutionUatRef: get("provider-uat-ref"), validUntil: get("provider-valid-until") }) }); setStatus("Provider evidence submitted. Production remains denied until independent approval and every admission gate passes."); ui.provider_form.reset(); await load(); } catch (error) { setStatus(error.message, true); } }
async function approveProviderEvidence(event) { const button = event.target.closest("[data-approve-provider]"); if (!button) return; const approvalRef = window.prompt("Independent provider-evidence approval reference:"); if (!approvalRef?.trim()) return; try { await request(`/ai/agents/provider-evidence/${encodeURIComponent(button.dataset.approveProvider)}/approve`, { method: "POST", body: JSON.stringify({ approvalRef: approvalRef.trim() }) }); setStatus("Provider evidence approved. LoanOS has reassessed production admission."); await load(); } catch (error) { setStatus(error.message, true); } }
function renderProviderEvidence() { const records = workspace.providerEvidence ?? []; if (!records.length) { ui.provider_list.className = "lifecycle-list empty"; ui.provider_list.textContent = "No provider evidence."; } else { ui.provider_list.className = "lifecycle-list"; ui.provider_list.replaceChildren(...records.map((item) => { const row = document.createElement("article"); row.className = "lifecycle-item"; row.append(text("strong", `${item.providerId} · ${item.status}`), text("small", `India region · valid until ${new Date(item.validUntil).toLocaleDateString("en-IN")}`)); if (item.status === "pending_approval") { const button = text("button", "Approve as independent checker"); button.type = "button"; button.className = "btn btn-secondary btn-sm"; button.dataset.approveProvider = item.evidenceId; row.append(button); } return row; })); } const admissions = workspace.productionAdmission ?? []; ui.admission_list.className = admissions.length ? "readiness-grid" : "readiness-grid empty"; ui.admission_list.replaceChildren(...(admissions.length ? admissions.map((item) => readinessItem(item.ready, `${item.installationId} · ${item.ready ? "admission controls pass" : "production denied"}`, item.ready ? "Repository evidence gates pass; institution authorization is still required." : item.reasons.join(", ").replaceAll("_", " "))) : [text("span", "Production admission remains denied.")])); }
function parseKnowledge(value) { return String(value || "").split("\n").map((line) => line.trim()).filter(Boolean).map((line) => { const [ref, version, contentHash] = line.split("|").map((part) => part.trim()); if (!ref || !version || !/^[a-f0-9]{64}$/i.test(contentHash ?? "")) throw new Error("Each knowledge source must be reference | version | 64-character SHA-256."); return { ref, version, contentHash }; }); }
function values(name) { return checkedValues(name === "commercialTemplates" ? ui.commercial_form : ui.agent_form, name); }
function split(value) { return String(value ?? "").split(",").map((item) => item.trim()).filter(Boolean); }
function slug(value) { return String(value).trim().toLowerCase().replaceAll(/[^a-z0-9]+/g, "-").replaceAll(/^-|-$/g, ""); }
function paiseToRupees(value) { return (BigInt(value ?? "0") / 100n).toLocaleString("en-IN") + (BigInt(value ?? "0") % 100n ? `.${(BigInt(value) % 100n).toString().padStart(2, "0")}` : ""); }
function downloadJson(name, value) { const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: "application/json" })); link.download = name; link.click(); URL.revokeObjectURL(link.href); }
function previewItem(title, detail) { const item = document.createElement("article"); item.className = "preview-item"; item.append(text("strong", title), text("span", detail)); return item; }
function readinessItem(good, title, detail) { const item = document.createElement("article"); item.className = `readiness-item ${good ? "good" : "warn"}`; item.append(text("strong", title), text("span", detail)); return item; }
function option(value, label) { const node = document.createElement("option"); node.value = value; node.textContent = label; return node; }
function text(tag, value) { const node = document.createElement(tag); node.textContent = value; return node; }
function escapeHtml(value) { const element = document.createElement("span"); element.textContent = value; return element.innerHTML; }
async function sha256(value) { const bytes = new TextEncoder().encode(value); const hash = await crypto.subtle.digest("SHA-256", bytes); return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, "0")).join(""); }
async function request(path, init = {}) { const response = await fetch(path, { headers: { "content-type": "application/json", ...(init.headers ?? {}) }, ...init }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error?.message ?? "The requested agent operation was blocked."); return body; }
function setStatus(message, error = false) { ui.status.textContent = message; ui.status.classList.toggle("error", error); }
function startMode(mode) {
  document.querySelectorAll("[data-start-mode]").forEach((button) => button.setAttribute("aria-pressed", String(button.dataset.startMode === mode)));
  if (mode === "copy") {
    const source = workspace.installations.at(-1);
    if (!source) return setStatus("There is no existing assistant to copy yet. Start with a banking template instead.", true);
    selectTemplate(source.templateId);
    ui.agent_form.elements.installationId.value = `${source.installationId}-copy`;
    ui.agent_form.elements.humanSponsorPrincipalId.value = source.humanSponsorPrincipalId;
    ui.agent_form.elements.products.value = (source.productTypes ?? []).join(", ");
    ui.agent_form.elements.languages.value = (source.languages ?? []).join(", ");
    ui.agent_form.elements.dataScopes.value = (source.dataScopes ?? []).join(", ");
    ui.agent_form.elements.instructions.value = `Adapt the approved instructions from ${source.promptRef}. Describe the new assistant's job here.`;
    ui.contract_id.value = source.contractId;
    ui.model.value = `${source.modelId}|${source.modelVersion}`;
    ui.agent_form.elements.workloadPrincipalId.value = `${source.workloadPrincipalId}-copy`;
    ui.agent_form.elements.configurationRef.value = `${source.configurationRef}-copy`;
    ui.action_scope.querySelectorAll("input").forEach((input) => { input.checked = source.allowedActions.includes(input.value); });
    setStatus("Existing assistant copied as a new draft. Review every field before sending it for approval.");
  } else if (mode === "guided") {
    const template = selectedTemplate ?? marketplace.templates[0];
    ui.agent_form.reset(); selectTemplate(template.templateId);
    ui.agent_form.elements.languages.value = "en-IN";
    setStatus("Guided setup started. Describe the job in everyday language; advanced controls inherit from the selected safe template.");
  } else {
    document.querySelector(".catalogue-panel")?.scrollIntoView({ behavior: "smooth", block: "start" });
    setStatus("Choose the banking pattern closest to the work your team performs.");
  }
}
